class Solution {
public:
    std::string findSmallestRegion(std::vector<std::vector<std::string>>& regions, std::string region1, std::string region2) {
        std::unordered_map<std::string, std::string> parent;
        for (const auto& r : regions) {
            for (int i = 1; i < r.size(); ++i) {
                parent[r[i]] = r[0];
            }
        }
        std::unordered_set<std::string> ancestors;
        std::string curr = region1;
        while (!curr.empty()) {
            ancestors.insert(curr);
            curr = parent.count(curr) ? parent[curr] : "";
        }
        curr = region2;
        while (!ancestors.count(curr)) {
            curr = parent[curr];
        }
        return curr;
    }
};

class Solution {
    public String findSmallestRegion(java.util.List<java.util.List<String>> regions, String region1, String region2) {
        java.util.Map<String, String> parent = new java.util.HashMap<>();
        for (java.util.List<String> r : regions) {
            String p = r.get(0);
            for (int i = 1; i < r.size(); i++) {
                parent.put(r.get(i), p);
            }
        }
        java.util.Set<String> ancestors = new java.util.HashSet<>();
        String curr = region1;
        while (curr != null) {
            ancestors.add(curr);
            curr = parent.get(curr);
        }
        curr = region2;
        while (!ancestors.contains(curr)) {
            curr = parent.get(curr);
        }
        return curr;
    }
}

var findSmallestRegion = function(regions, region1, region2) {
    const parent = new Map();
    for (const r of regions) {
        const p = r[0];
        for (let i = 1; i < r.length; i++) {
            parent.set(r[i], p);
        }
    }
    const ancestors = new Set();
    let curr = region1;
    while (curr) {
        ancestors.add(curr);
        curr = parent.get(curr);
    }
